const selected = ref(0)
watch(() => props.pageKey, () => selected.value = 0)
</script>

<template>
 <section v-if="content" class="section-editorial" :key="pageKey" aria-label="栏目导览">
  <div class="editorial-heading"><div><p>{{ content.label }}</p><h2>{{ content.title }}</h2></div><span>{{ content.intro }}</span></div>
  <div class="editorial-feature"><figure><img :src="'/images/' + content.image" :alt="content.caption" decoding="async"><figcaption>{{ content.caption }}</figcaption><span aria-hidden="true">{{ pageKey.toUpperCase() }}</span></figure><div class="editorial-feature-copy"><p class="editorial-eyebrow">A CLOSER LOOK / 换个角度看敦煌</p><div class="editorial-tabs" role="tablist" aria-label="导览主题"><button v-for="(tab,i) in content.tabs" :id="`${pageKey}-insight-tab-${i}`" :key="tab[0]" role="tab" :aria-selected="selected === i" :aria-controls="`${pageKey}-insight-panel`" @click="selected = i" @keydown.right.prevent="selected = (selected + 1) % content.tabs.length; $event.currentTarget.parentElement.children[selected].focus()" @keydown.left.prevent="selected = (selected + content.tabs.length - 1) % content.tabs.length; $event.currentTarget.parentElement.children[selected].focus()">{{ tab[0] }}</button></div><div :id="`${pageKey}-insight-panel`" role="tabpanel" :aria-labelledby="`${pageKey}-insight-tab-${selected}`" class="editorial-insight"><div :key="selected"><span class="editorial-number" aria-hidden="true">0{{ selected + 1 }}</span><h3>{{ content.tabs[selected][1] }}</h3><p>{{ content.tabs[selected][2] }}</p></div></div><span class="editorial-counter"><i v-for="(_,i) in content.tabs" :key="i" :class="{ active: selected === i }"></i><small>0{{ selected + 1 }} / 03</small></span></div></div>
 </section>
</template>

